lazy import sys, os, ast
lazy from importlib.abc import MetaPathFinder, SourceLoader
lazy from importlib.machinery import ModuleSpec

from typing import Sequence

class CustomFinder(MetaPathFinder):
    def find_spec(self, fullname: str, path: Sequence[str]|None, target=None):
        filename = f"{fullname}.py"
        if os.path.exists(filename):
            return ModuleSpec(fullname,CustomLoader(fullname, filename), origin=filename)
        return None  # Fallback to standard Python finders

class CustomLoader(SourceLoader):
    def __init__(self, fullname: str, path: Sequence[str]|None):
        self.fullname = fullname
        self.path = path
    def get_filename(self, fullname: str):
        return self.path
    def get_data(self, path: str):
        with open(path) as f:
            data = f.read()
            data = 'print("added in get_data...")\n' + data
            return data
    def source_to_code(self, data, path, fullname = "", *, _optimize=-1):
        data = 'print("added in source_to_code...")\n' + data
        return compile(data, path, "exec", optimize=_optimize)

if __name__ == "__main__":
    sys.meta_path.insert(0, CustomFinder())
    import Module1

